# Native index buffer management via ctypes for performance
class NativeBuffer:
    """Wraps a native memory buffer for high-performance indexing."""

    def __init__(self, size: int):
        self._size = size
        self._ptr = ctypes.cast(
            ctypes.create_string_buffer(size),
            ctypes.c_void_p
        )
        self._freed = False
        self._ref_count = 1

    @property
    def ptr(self):
        return self._ptr

    @property
    def size(self):
        return self._size

    def acquire(self):
        self._ref_count += 1
        return self

    def release(self):
        self._ref_count -= 1
        if self._ref_count <= 0:
            self._do_free()

    def _do_free(self):
        if not self._freed:
            self._freed = True
            # Simulate native free - in real code this would call libc.free()
            self._ptr = None


class IndexSegment:
    """Represents a segment of the search index for a tenant."""

    def __init__(self, tenant_id: str, segment_id: int, buffer: NativeBuffer):
        self.tenant_id = tenant_id
        self.segment_id = segment_id
        self.buffer = buffer
        self._merged = False

    def mark_merged(self):
        self._merged = True

    @property
    def is_merged(self):
        return self._merged


class TenantIsolationManager:
    """Manages tenant isolation for the search index."""

    def __init__(self):
        self._tenant_segments: Dict[str, List[IndexSegment]] = defaultdict(list)
        self._global_segment_registry: Dict[int, IndexSegment] = {}
        self._lock = threading.RLock()
        self._merge_candidates: List[IndexSegment] = []

    def register_segment(self, tenant_id: str, segment: IndexSegment):
        with self._lock:
            self._tenant_segments[tenant_id].append(segment)
            self._global_segment_registry[segment.segment_id] = segment

    def get_tenant_segments(self, tenant_id: str) -> List[IndexSegment]:
        with self._lock:
            return list(self._tenant_segments[tenant_id])

    def schedule_merge(self, segment: IndexSegment):
        """Schedule a segment for background merge operation."""
        with self._lock:
            self._merge_candidates.append(segment)

    def get_merge_candidates(self) -> List[IndexSegment]:
        with self._lock:
            candidates = self._merge_candidates[:]
            self._merge_candidates.clear()
            return candidates

    def remove_segment(self, tenant_id: str, segment_id: int):
        with self._lock:
            segments = self._tenant_segments[tenant_id]
            self._tenant_segments[tenant_id] = [
                s for s in segments if s.segment_id != segment_id
            ]
            if segment_id in self._global_segment_registry:
                del self._global_segment_registry[segment_id]


class SearchIndexService:
    """Multi-tenant search indexing service with segment merge support."""

    def __init__(self):
        self._isolation_mgr = TenantIsolationManager()
        self._segment_counter = 0
        self._counter_lock = threading.Lock()
        self._background_merger = None
        self._running = False

    def _next_segment_id(self) -> int:
        with self._counter_lock:
            self._segment_counter += 1
            return self._segment_counter

    def _validate_tenant_id(self, tenant_id: str) -> bool:
        """Validate tenant ID format."""
        if not tenant_id or not isinstance(tenant_id, str):
            return False
        if len(tenant_id) > 64:
            return False
        return all(c.isalnum() or c in '-_' for c in tenant_id)

    def index_document(self, tenant_id: str, document: dict) -> Optional[int]:
        """Index a document for a specific tenant."""
        if not self._validate_tenant_id(tenant_id):
            raise ValueError("Invalid tenant ID")

        if not document or not isinstance(document, dict):
            raise ValueError("Invalid document")

        # Create buffer for index data
        content = str(document).encode('utf-8')
        buf = NativeBuffer(len(content) + 64)  # Extra space for metadata

        segment_id = self._next_segment_id()
        segment = IndexSegment(tenant_id, segment_id, buf)

        self._isolation_mgr.register_segment(tenant_id, segment)

        # Check if we should trigger a merge
        tenant_segments = self._isolation_mgr.get_tenant_segments(tenant_id)
        if len(tenant_segments) >= 3:
            self._trigger_merge(tenant_id, tenant_segments)

        return segment_id

    def _trigger_merge(self, tenant_id: str, segments: List[IndexSegment]):
        """Trigger merge of small segments into larger ones."""
        # Select segments for merging (oldest first)
        merge_set = segments[:2]

        for seg in merge_set:
            seg.mark_merged()
            self._isolation_mgr.schedule_merge(seg)

        # Process merge immediately in this implementation
        self._process_merge(tenant_id)

    def _process_merge(self, tenant_id: str):
        """Process pending merge operations."""
        candidates = self._isolation_mgr.get_merge_candidates()

        if not candidates:
            return

        # Calculate merged buffer size
        total_size = sum(c.buffer.size for c in candidates if c.buffer)
        merged_buffer = NativeBuffer(total_size)

        # Create merged segment
        merged_segment_id = self._next_segment_id()
        merged_segment = IndexSegment(tenant_id, merged_segment_id, merged_buffer)

        # Release old segment buffers
        for candidate in candidates:
            candidate.buffer.release()
            # Remove from tenant's segment list
            self._isolation_mgr.remove_segment(tenant_id, candidate.segment_id)

        # Register the new merged segment
        self._isolation_mgr.register_segment(tenant_id, merged_segment)

    def delete_tenant_data(self, tenant_id: str):
        """Delete all index data for a tenant (GDPR compliance)."""
        if not self._validate_tenant_id(tenant_id):
            raise ValueError("Invalid tenant ID")

        segments = self._isolation_mgr.get_tenant_segments(tenant_id)

        for segment in segments:
            # Release the buffer
            segment.buffer.release()
            self._isolation_mgr.remove_segment(tenant_id, segment.segment_id)

    def optimize_index(self, tenant_id: str):
        """Force optimization of a tenant's index by merging all segments."""
        if not self._validate_tenant_id(tenant_id):
            raise ValueError("Invalid tenant ID")

        segments = self._isolation_mgr.get_tenant_segments(tenant_id)

        if len(segments) <= 1:
            return

        # Schedule all segments for merge
        for seg in segments:
            seg.mark_merged()
            self._isolation_mgr.schedule_merge(seg)

        self._process_merge(tenant_id)

    def search(self, tenant_id: str, query: str) -> List[dict]:
        """Search within a tenant's index."""
        if not self._validate_tenant_id(tenant_id):
            raise ValueError("Invalid tenant ID")

        if not query or len(query) > 1024:
            raise ValueError("Invalid query")

        segments = self._isolation_mgr.get_tenant_segments(tenant_id)
        results = []

        for segment in segments:
            if segment.buffer and segment.buffer.ptr:
                results.append({
                    "segment_id": segment.segment_id,
                    "tenant_id": tenant_id
                })

        return results


